import{_ as e,o as a,c,a2 as r}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Network Cache (DNS Cache)","description":"","frontmatter":{},"headers":[],"relativePath":"notes/cache.md","filePath":"notes/cache.md"}'),n={name:"notes/cache.md"};function h(o,t,i,s,l,u){return a(),c("div",null,[...t[0]||(t[0]=[r('<h1 id="network-cache-dns-cache" tabindex="-1">Network Cache (DNS Cache) <a class="header-anchor" href="#network-cache-dns-cache" aria-label="Permalink to &quot;Network Cache (DNS Cache)&quot;">​</a></h1><p>Khái niệm cache xuất hiện ở rất nhiều nơi, không chỉ ở server mà còn ở browser và DNS.</p><h2 id="dns-cache" tabindex="-1">DNS Cache <a class="header-anchor" href="#dns-cache" aria-label="Permalink to &quot;DNS Cache&quot;">​</a></h2><blockquote><p>Tham khảo: <a href="https://www.youtube.com/watch?v=PI9-kQST_BM" target="_blank" rel="noreferrer">video giải thích DNS</a></p></blockquote><p>DNS cache hỗ trợ việc tra cứu nhanh địa chỉ IP của một server/domain, được lưu ở nhiều lớp khác nhau: browser, hệ điều hành, router, và ISP.</p><p>Thứ tự tra cứu khi nhập một URL và nhấn Enter:</p><ol><li>Tìm trong <strong>DNS cache của trình duyệt (browser)</strong>.</li><li>Nếu không có, tìm tiếp trong <strong>cache của hệ điều hành (OS)</strong>.</li><li>Nếu không có, tìm tiếp trong <strong>cache của router</strong>.</li><li>Nếu không có, tìm tiếp trong <strong>cache của ISP</strong> (ví dụ VNPT, Viettel — kiểm tra xem đã từng có request tới domain này trước đó chưa).</li><li>Nếu ISP cũng không có, ISP sẽ gửi truy vấn tới các <strong>DNS server</strong> để tìm domain này đang khớp với địa chỉ IP nào, rồi trả kết quả ngược về qua từng lớp cache ở trên.</li></ol>',7)])])}const m=e(n,[["render",h]]);export{d as __pageData,m as default};
